use togi_sim::MachineDefinition;
use togi_sim::file::{self, EncodeError};
use togi_tool_modelcheck::Group;

use crate::signals::signals_note;

fn group_note(prefix: &str, group: &Group) -> String {
    format!("{prefix}: {group}")
}

/// The machine file of fit `index`: `cfg` with provenance and diagnostics in its `notes`.
pub(crate) fn encode_machine(
    cfg: &MachineDefinition,
    index: usize,
    seed: u64,
    trials: usize,
    loss: f64,
    constrained: &[Group],
    flagged: &[Group],
) -> Result<String, EncodeError> {
    let mut notes = vec![
        "Generated by togi-tool-fit".to_owned(),
        format!(
            "Whole-trial bootstrap: index={index} (0=all facts), seed={seed}, trials={trials}, negative_log_likelihood={loss}"
        ),
        signals_note(&cfg.model),
    ];
    for group in constrained {
        notes.push(group_note("Constrained bootstrap", group));
    }
    if flagged.is_empty() {
        notes.push("Model check against the original extract: ok, no flagged groups.".to_owned());
    } else {
        notes.push("Model check against the original extract: flagged.".to_owned());
    }
    for group in flagged {
        notes.push(format!(
            "{} interval=[{},{}]",
            group_note("Flagged", group),
            group.interval.low,
            group.interval.high
        ));
    }
    with_notes(cfg, notes)
}

pub(crate) fn encode_shared_voltage_anchor(
    cfg: &MachineDefinition,
    trials: usize,
    loss: f64,
) -> Result<String, EncodeError> {
    let notes = vec![
        "Generated by togi-tool-fit --shared-voltage-in-sample".to_owned(),
        "IN-SAMPLE all-facts shared-voltage anchor; NOT forward-validated.".to_owned(),
        "The first candidate failed the 2026-10-04 #306 R7 forward bar: 36.0 predicted / 17 observed (>2x)."
            .to_owned(),
        "That check was not blind; a future forward claim needs a new blind session.".to_owned(),
        format!("All decisive trials={trials}; raw Bernoulli negative_log_likelihood={loss}"),
        "Checked against every eligible group of the full original extract before writing.".to_owned(),
        signals_note(&cfg.model),
    ];
    with_notes(cfg, notes)
}

fn with_notes(cfg: &MachineDefinition, notes: Vec<String>) -> Result<String, EncodeError> {
    let mut cfg = cfg.clone();
    cfg.notes = notes;
    file::encode(&cfg)
}
